def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue

        event_id = event.get('id') if 'id' in event else ('anonymous', position)
        revision = event.get('revision', 0)
        previous = winners.get(event_id)
        if previous is None or (revision, position) >= (previous[0], previous[1]):
            winners[event_id] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    mode = data.get('rounding', 'floor')

    for _, _, event in winners.values():
        if event.get('void', False) is True:
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        value = amount(event, mode)
        if event.get('kind') == 'refund':
            value = -value
        balances[key] += value

    return {'balances': balances}
